using System.Buffers.Binary;
using System.Text.Json;
using Spyro.Editor.Core.Exporting;
using Spyro.Editor.Core.Universal;

if(args.Length==2&&args[0]=="--emit-packaged-core")
{
    string path=Path.GetFullPath(args[1]);
    var context=new System.Runtime.Loader.AssemblyLoadContext("native-save-map-package-check",true);
    var assembly=context.LoadFromAssemblyPath(path);
    var type=assembly.GetType("Spyro.Editor.Core.Exporting.NativeMobySaveMap",true)!;
    var result=(System.Collections.IEnumerable)type.GetMethod("Windows")!.Invoke(null,null)!;
    List<object> emitted=[];
    foreach(object window in result)
    {
        var record=window.GetType();
        emitted.Add(new{address=(uint)record.GetProperty("Address")!.GetValue(window)!,code=Convert.ToHexString((byte[])record.GetProperty("Code")!.GetValue(window)!),sourceSha256=(string)record.GetProperty("SourceSha256")!.GetValue(window)!});
    }
    Console.WriteLine(JsonSerializer.Serialize(new{marker="NATIVE_MOBY_SAVE_MAP_PACKAGED_CORE_OK",moduleSha256=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(path))),windows=emitted}));
    return;
}

int checks=0;
