BinaryPrimitives.WriteUInt32LittleEndian(exe.AsSpan((int)(NativeMobySaveMap.EmptyReloadBranchAddress-UniversalExeBindings.ExeBase)),0x10620046);
byte[] sourceExe=exe.ToArray();
byte[] badSecond=sourceExe.ToArray();badSecond[(int)(NativeMobySaveMap.ReloadAddress-UniversalExeBindings.ExeBase)+80]^=1;
byte[] badSecondBefore=badSecond.ToArray();
bool rejectedSecond=false;try{NativeMobySaveMap.PatchExe(badSecond);}catch(InvalidDataException){rejectedSecond=true;}
Check(rejectedSecond&&badSecond.SequenceEqual(badSecondBefore),"all owner preimages validated before any mutation");
NativeMobySaveMap.PatchExe(exe);byte[] once=exe.ToArray();NativeMobySaveMap.PatchExe(exe);
Check(exe.SequenceEqual(once),"canonical native hooks idempotent");
exe[(int)(NativeMobySaveMap.MarkAddress-UniversalExeBindings.ExeBase)+80]^=1;
bool refused=false;try{NativeMobySaveMap.PatchExe(exe);}catch(InvalidDataException){refused=true;}Check(refused,"unrecognized native owner rejected");
uint start=UniversalOverlay.Base,copy=start+0x800;
var bindings=new Dictionary<uint,UniversalExeBinding>{[UniversalExeBindings.UpdateGlobal]=new(UniversalExeBindings.UpdateGlobal,0,0,start),[UniversalExeBindings.InitGlobal]=new(UniversalExeBindings.InitGlobal,0,0,start),[UniversalExeBindings.CopyBufferGlobal]=new(UniversalExeBindings.CopyBufferGlobal,0,0,copy)};
byte[] native=new byte[0x800];var original=new UniversalOverlay(native,bindings);
int[] map=[1,-1,255,0,31,32];
var overlay=NativeMobySaveMap.Append(original,native,start,copy,map);
Check(overlay.CopyBuffer>copy&&overlay.UpdatePointer==copy+12,"mapping resident growth is explicit");
Check(native.SequenceEqual(overlay.Overlay.AsSpan(0,native.Length).ToArray()),"native overlay bytes retained");
byte[] signedNative=new byte[0x800];
uint signedUpdate=start+32;
BinaryPrimitives.WriteUInt32LittleEndian(signedNative.AsSpan(20),UniversalSpecialBehaviors.SignHookMarker);
BinaryPrimitives.WriteUInt32LittleEndian(signedNative.AsSpan(24),UniversalMips.EncodeJ(2,start+64));
var signedMap=NativeMobySaveMap.Append(original,signedNative,signedUpdate,copy,map);
Check(signedMap.Overlay.AsSpan((int)(signedMap.UpdatePointer-start)-12,12).SequenceEqual(signedNative.AsSpan(20,12)),"verified native sign prefix survives mapping wrapper");
BinaryPrimitives.WriteUInt32LittleEndian(signedNative.AsSpan(28),1);
refused=false;try{_=NativeMobySaveMap.Append(original,signedNative,signedUpdate,copy,map);}catch(InvalidDataException){refused=true;}Check(refused,"unverified sign delay refused");
var identity=NativeMobySaveMap.Append(original,native,start,copy,[0,1,2]);
Check(ReferenceEquals(identity.Overlay,native)&&identity.CopyBuffer==copy,"identity layout no-op");
foreach(int[] bad in new[]{new[]{256},new[]{-2},new[]{0,0},Enumerable.Range(0,257).ToArray()})
{refused=false;try{_=NativeMobySaveMap.Append(original,native,start,copy,bad);}catch(InvalidDataException){refused=true;}Check(refused,"invalid map rejected");}
int[] eggMap=Enumerable.Repeat(-1,197).ToArray();eggMap[0]=195;eggMap[196]=197;
var eggOverlay=NativeMobySaveMap.Append(original,native,start,copy,eggMap);
const uint eggAddress=0x800A0000;
byte[] eggCode=UniversalSpecialBehaviors.DragonflyEggUpdateCode(UniversalDragonflyEggs.Variants.Select(v=>v.Class).ToArray(),eggAddress,true);
if(args.Contains("--emit"))
{
